import { getImageProps } from "next/image";
import { preload } from "react-dom";
import { cn } from "@/lib/utils";

// public/brand/logo.png is 266×271 (generated by `pnpm icons`).
const RATIO = 271 / 266;

interface LogoProps {
  /** Rendered width of the mark in CSS pixels. */
  size: number;
  className?: string;
  priority?: boolean;
}

/**
 * The Solace logo on a white circle, so its white gaps stay readable on any
 * background. Never redraw or recolour it (CLAUDE.md, Brand & logo).
 *
 * `getImageProps` gives the same optimised `<img>` as `next/image` without
 * shipping its client component, so the logo adds no JavaScript (PRD 14).
 */
export function Logo({ size, className, priority = false }: LogoProps) {
  const padding = Math.round(size * 0.08);
  const { props } = getImageProps({
    src: "/brand/logo.png",
    alt: "Solace",
    width: size,
    height: Math.round(size * RATIO),
    priority,
    style: { width: size, height: "auto" },
  });
  // next/image preloads priority images the same way.
  if (priority) {
    preload(props.src, {
      as: "image",
      imageSrcSet: props.srcSet,
      imageSizes: props.sizes,
      fetchPriority: props.fetchPriority,
    });
  }

  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-full bg-white",
        className,
      )}
      style={{ width: size + padding * 2, height: size + padding * 2 }}
    >
      {/* eslint-disable-next-line @next/next/no-img-element -- props come from getImageProps */}
      <img {...props} alt="Solace" data-nimg="1" />
    </span>
  );
}
